export const getUpdateDebtUrl = (id: string) => {
  return `/api/debts/${id}`;
};

/**
 * Records a new outstanding balance, rate, or name. This is how repayment progress is tracked: lower outstandingAmount as the debt is paid down.
 * @summary Update a debt
 */
export const updateDebt = async (
  id: string,
  updateDebtRequest: UpdateDebtRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<DebtResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<DebtResponse>(getUpdateDebtUrl(id), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(updateDebtRequest),
  });
};

export const getUpdateDebtMutationKey = () => ["updateDebt"] as const;

export const getUpdateDebtMutationOptions = <
  TError = ErrorType<ProblemDetails>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateDebt>>,
    TError,
    UpdateDebtMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateDebt>>,
  TError,
  UpdateDebtMutationVariables,
  TContext
> => {
  const mutationKey = getUpdateDebtMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateDebt>>,
    UpdateDebtMutationVariables
  > = (props) => {
    const { id, data } = props ?? {};

    return updateDebt(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

